select energy_manager.load_cards($cards$[
{"id":"p3-b04-020","paper":3,"topic":"Condensers and evaporators","kind":"fact","front":"With R-22, how much extra energy does an air-cooled condenser need compared with a water-cooled shell-and-tube condenser?","back":"About 30% more. The air-cooled condenser ran at about 20 kg/cm² discharge pressure against about 15 kg/cm² for the water-cooled one.","explain":"Higher discharge pressure adds compression work. The book recommends generously sized shell-and-tube water-cooled condensers (about 0.65 m² per TR and above) at the design stage.","flash":false,"source":"BEE Book 3 Ch 04 p153","order":3242},
{"id":"p3-b04-021","paper":3,"topic":"Condensers and evaporators","kind":"fact","front":"By roughly how much does compressor power change for each 1°C rise in evaporator temperature?","back":"It falls by about 3%. The same machine also gains TR capacity as evaporator temperature rises.","explain":"A higher evaporator temperature raises suction pressure, which cuts the work of compression. The book advises the highest evaporator temperature the process can accept, with heat transfer areas sized to keep the driving temperature difference small.","flash":false,"source":"BEE Book 3 Ch 04 p153","order":3243},
{"id":"p3-b04-022","paper":3,"topic":"Condensers and evaporators","kind":"fact","front":"How much extra energy can a 0.8 mm scale build-up on condenser tubes cause?","back":"Up to about 35% more energy consumption.","explain":"Fouled condenser tubes force the compressor to work harder for the same capacity. Fouled evaporators from residual lubricating oil or air infiltration also raise power use, so regular cleaning is a standard saving.","flash":false,"source":"BEE Book 3 Ch 04 p154","order":3244},
{"id":"p3-b04-023","paper":3,"topic":"Refrigeration cycles","kind":"fact","front":"What is the difference between a cascade system and a compound (two-stage) system, and which applies at -46°C to -101°C?","back":"Compound systems use one refrigerant with two compressors sharing the work of compression, used roughly from -20°C to -58°C. Cascade systems connect two separate systems with different refrigerants, one rejecting heat to the other, and are preferred for -46°C to -101°C.","explain":"In a cascade, a low-temperature refrigerant with high suction temperature and low specific volume can be chosen for the low stage. Two compressors with low compression ratios together give a high overall ratio in a compound system.","flash":false,"source":"BEE Book 3 Ch 04 p155","order":3245},
{"id":"p3-b04-024","paper":3,"topic":"Compressors","kind":"fact","front":"Why is it more efficient to run one chiller at full load than two at part load?","back":"Part-load operation of a chiller bank is inefficient, so each compressor should be loaded to full capacity before the next one starts.","explain":"Isolation valves should stop chilled water flowing through idle chillers. Valves on idle branch lines also cut pressure drop and pumping power.","flash":false,"source":"BEE Book 3 Ch 04 p156","order":3246},
{"id":"p3-b04-025","paper":3,"topic":"Refrigeration performance","kind":"fact","front":"What is the Energy Efficiency Ratio (EER) of an air conditioner, and which labelling programme uses this definition?","back":"Cooling capacity in watts divided by power input in watts at full-load conditions. The BEE star labelling programme uses this definition.","explain":"Air properties from the psychrometric chart give the delivered capacity, which is then compared with power drawn to get kW/TR and EER. EER in W/W is the same as kW/kW.","flash":true,"source":"BEE Book 3 Ch 04 p157","order":3247},
{"id":"p3-b04-026","paper":3,"topic":"Air conditioner rating","kind":"problem","front":"A package air conditioner has 4751 m³/h of air flow, inlet enthalpy 9.37 kcal/kg, outlet enthalpy 7.45 kcal/kg and specific volume 0.8405 m³/kg. Its compressor draws 4.71 kW, pump 2.14 kW and cooling tower fan 0.384 kW. Find the cooling delivered in TR, compressor kW/TR, overall kW/TR and EER.","back":"About 3.6 TR (12.7 kW); compressor 1.31 kW/TR; overall about 2.0 kW/TR; EER about 2.95 W/W using the book's 4.3 kW shaft power.","explain":"The book's example is a 10 TR package unit running only one of its two 5 TR compressors at low load. The book's EER uses 4.3 kW shaft power at 90% motor efficiency, not the 4.71 kW input.","flash":false,"source":"BEE Book 3 Ch 04 p158","steps":[{"prompt":"Find the mass flow of air.","answer":"4751 m³/h ÷ 0.8405 m³/kg ≈ 5653 kg/h.","explain":"Specific volume converts the volume flow to mass flow."},{"prompt":"Find the heat removed and convert to TR.","answer":"Enthalpy drop 9.37 − 7.45 = 1.92 kcal/kg; 5653 × 1.92 ≈ 10,850 kcal/h; ÷ 3024 ≈ 3.6 TR (about 12.7 kW).","explain":"1 TR = 3024 kcal/h of heat removal."},{"prompt":"Compute the compressor kW/TR.","answer":"4.71 kW ÷ 3.6 TR ≈ 1.31 kW/TR.","explain":"Compressor-only specific power is the usual first check."},{"prompt":"Compute the overall kW/TR.","answer":"(4.71 + 2.14 + 0.384) kW ÷ 3.6 TR ≈ 2.0 kW/TR.","explain":"Overall includes compressor, pump and cooling tower fan."},{"prompt":"Compute the EER.","answer":"12.7 kW ÷ 4.3 kW ≈ 2.95 W/W (book value).","explain":"The book uses shaft power here, which gives a higher EER than using input power."}],"order":3248},
{"id":"p3-b04-027","paper":3,"topic":"Heat pumps","kind":"fact","front":"How much electricity does an electrically driven heat pump need to supply 100 kWh of heat?","back":"About 20–40 kWh for building heating; many industrial heat pumps need only 3–10 kWh.","explain":"A heat pump moves heat from air, ground, water or waste heat to a higher temperature. The heat delivered equals the heat extracted plus the drive energy supplied.","flash":false,"source":"BEE Book 3 Ch 04 p160","order":3249},
{"id":"p3-b04-028","paper":3,"topic":"Heat pumps","kind":"problem","front":"In the book's heat pump example, the heat pump takes 3 units of energy from the surroundings and 1 unit of compressor work. What is its heating COP?","back":"4 (4 units of heat delivered per unit of work).","explain":"The figure shows the heat pump delivering 3 units from the surroundings plus 1 unit of work as 4 units at a higher temperature. Its heating COP is therefore 4.","flash":false,"source":"BEE Book 3 Ch 04 p160","steps":[{"prompt":"Identify the heat taken from the surroundings.","answer":"3 units.","explain":"This comes from the heat source (air, ground or water)."},{"prompt":"Identify the drive energy.","answer":"1 unit of compressor work (electricity).","explain":"The compressor is the only energy input."},{"prompt":"Find the heat delivered at higher temperature.","answer":"3 + 1 = 4 units.","explain":"Heat extracted plus drive energy equals heat delivered."},{"prompt":"Compute the heating COP.","answer":"4 ÷ 1 = 4.","explain":"Compare with building heat pumps needing 20–40 kWh per 100 kWh of heat (COP 2.5–5)."}],"order":3250},
{"id":"p3-b04-029","paper":3,"topic":"Ventilation","kind":"fact","front":"What are typical air changes per hour (ACH) for an office and for a welding shop?","back":"Offices: 6–10 ACH. Welding shops: 15–30 ACH.","explain":"Other values in the book: boiler rooms and engine rooms 15–30; compressor rooms 10–12; conference rooms 10–20; lavatories 6–15. Ventilation rate in m³/h equals room volume times ACH.","flash":false,"source":"BEE Book 3 Ch 04 p161","order":3251},
{"id":"p3-b04-030","paper":3,"topic":"Ventilation","kind":"problem","front":"A compressor room is 15 m long, 10 m wide and 4 m high. What ventilation rate in m³/h is needed at 10 ACH?","back":"6000 m³/h.","explain":"The book uses 10 ACH for a compressor room (range 10–12). Ventilation rate = L × B × H × ACH.","flash":false,"source":"BEE Book 3 Ch 04 p161","steps":[{"prompt":"Find the room volume.","answer":"15 × 10 × 4 = 600 m³.","explain":"Volume is length times breadth times height."},{"prompt":"Choose the air change rate.","answer":"10 ACH (book range for compressor rooms: 10–12).","explain":"Pick the value within the table range for the room type."},{"prompt":"Compute the ventilation rate.","answer":"600 m³ × 10 = 6000 m³/h.","explain":"ACH converts room volume into hourly air flow."}],"order":3252},
{"id":"p3-b04-031","paper":3,"topic":"Thermal storage","kind":"fact","front":"What do ice bank (thermal storage) systems do, and what do they save?","back":"They make and store ice at night on cheap off-peak power, then use the cooling in the day. This cuts peak demand and operating cost. In partial storage the chiller can be 40–50% smaller.","explain":"ICEBANK tanks range from about 45 to over 500 ton-hours. Extending the chiller's hours of operation gives the lowest possible average load.","flash":false,"source":"BEE Book 3 Ch 04 p162","order":3253},
{"id":"p3-b04-032","paper":3,"topic":"Humidification","kind":"fact","front":"How is the mass of water added to humidify air calculated?","back":"m_w = v × ρ × (w_out − w_in), where v is air flow (m³/h), ρ is air density (kg/m³), w is specific humidity (kg/kg) and m_w is water added (kg/h).","explain":"Specific humidity is the mass of moisture per kg of dry air. Air density varies with temperature; the book uses 1.184 kg/m³ at 25°C in its textile example.","flash":false,"source":"BEE Book 3 Ch 04 p163","order":3254},
{"id":"p3-b04-033","paper":3,"topic":"Humidification","kind":"problem","front":"An air washer in a textile plant humidifies 3000 m³/h of air at 25°C from 10% to 60% RH by spray water. Specific humidity rises from 0.002 to 0.0062 kg/kg. How much water is needed?","back":"About 14.9 kg/h.","explain":"Water is added without heat, so the air moves along a constant enthalpy line and only its moisture content rises. The formula is m_w = v × ρ × (w_out − w_in).","flash":false,"source":"BEE Book 3 Ch 04 p163","steps":[{"prompt":"Take the air density at 25°C.","answer":"1.184 kg/m³ (value used in the book).","explain":"Density is needed to turn volume flow into mass flow."},{"prompt":"Find the change in specific humidity.","answer":"0.0062 − 0.002 = 0.0042 kg/kg.","explain":"This is the moisture added per kg of dry air."},{"prompt":"Compute the water added.","answer":"3000 × 1.184 × 0.0042 ≈ 14.9 kg/h.","explain":"Multiply volume flow, density and moisture change."}],"order":3255},
{"id":"p3-b04-034","paper":3,"topic":"Energy saving measures","kind":"fact","front":"Name three energy saving measures for an air conditioning system.","back":"Any three of: insulating all cold lines and vessels at economic thickness; minimising the air conditioning load (roof cooling, false ceilings, efficient lighting, pre-cooling fresh air, variable air volume, sun film); minimising process heat loads (flow optimisation, avoiding idle flows, frequent heat exchanger cleaning); regular plant maintenance; matching plant to load with variable speed drives.","explain":"The book groups these into cold insulation, building envelope, building heat loads, process heat loads and plant-area measures. Naming the group along with the measure reads well in an exam answer.","flash":false,"source":"BEE Book 3 Ch 04 p164","order":3256},
{"id":"p3-b04-035","paper":3,"topic":"Air conditioner rating","kind":"problem","front":"Under the star rating bands valid 1 January 2014 to 31 December 2015, which star rating does a split air conditioner with an EER of 3.2 W/W get?","back":"3 star (band 3.10–3.29 W/W for split units).","explain":"The same EER falls in the 3.10–3.29 band on the unitary table too, but that table also gives 4 star for this band. Always check whether the unit is split or unitary before reading the star.","flash":false,"source":"BEE Book 3 Ch 04 p164","steps":[{"prompt":"Identify the correct table and period.","answer":"Split type, valid 1 January 2014 to 31 December 2015: Table 4.8.","explain":"The bands changed for later periods, so the date matters."},{"prompt":"Find the band that contains EER 3.2 W/W.","answer":"Band 3.10 to 3.29 W/W.","explain":"Bands are read from the minimum to maximum of each star row."},{"prompt":"Read the star rating.","answer":"3 star.","explain":"Unitary units use Table 4.9, where the same band is 4 star. Do not mix the tables."}],"order":3257},
{"id":"p3-b04-036","paper":3,"topic":"Energy saving measures","kind":"problem","front":"A compressor draws an average of 57.6 kW over 250 days of 10 hours each. The book reports 136,435 kWh/yr saved. At Rs 6/kWh, what is the annual cost saving?","back":"Rs 8,18,610 per year (136,435 kWh × Rs 6/kWh).","explain":"The book's average 57.6 kW over 2,500 h would give about 144,000 kWh, slightly above the reported 136,435 kWh. The reported figure implies an average near 54.6 kW, so use the book's annual value if a question quotes it.","flash":false,"source":"BEE Book 3 Ch 04 p167","steps":[{"prompt":"Find the operating hours per year.","answer":"250 days × 10 h = 2,500 h/yr.","explain":"This is the schedule the book assumes."},{"prompt":"Take the annual energy saving.","answer":"136,435 kWh/yr (as reported in the book).","explain":"Energy saved by variable speed drive over the year."},{"prompt":"Compute the annual monetary saving.","answer":"136,435 kWh × Rs 6/kWh = Rs 8,18,610 per year.","explain":"Energy saving times the tariff gives the cost saving."}],"order":3258},
{"id":"p3-b04-037","paper":3,"topic":"Compressors","kind":"problem","front":"A 20 TR package air conditioner has an average air velocity of 2.5 m/s across a 1.2 m² suction area. Inlet air is 9.37 kcal/kg enthalpy, outlet 7.45 kcal/kg, specific volume 0.85 m³/kg. Power drawn: compressor 10.69 kW, pump 4.86 kW, cooling tower fan 0.87 kW. Find the air flow, cooling delivered, compressor kW/TR, overall kW/TR and EER.","back":"Air flow 10,800 m³/h; cooling 8.07 TR (about 28.3 kW); compressor 1.32 kW/TR; overall about 2.04 kW/TR (book value); EER 2.65 kW/kW.","explain":"The book's worked solution takes airflow as velocity times area. The overall kW/TR includes pump and tower fan power, not only the compressor.","flash":false,"source":"BEE Book 3 Ch 04 p168","steps":[{"prompt":"Find the air flow rate.","answer":"2.5 m/s × 1.2 m² = 3 m³/s = 10,800 m³/h.","explain":"Velocity times cross-section gives volume flow."},{"prompt":"Find the cooling effect in TR.","answer":"(9.37 − 7.45) × 10,800 ÷ (0.85 × 3024) ≈ 8.07 TR ≈ 28.3 kW.","explain":"Mass flow is volume flow divided by specific volume; then multiply by enthalpy drop."},{"prompt":"Find the compressor kW/TR.","answer":"10.69 kW ÷ 8.07 TR ≈ 1.32 kW/TR.","explain":"Compressor-only specific power."},{"prompt":"Find the overall kW/TR.","answer":"(10.69 + 4.86 + 0.87) kW ÷ 8.07 TR ≈ 2.03–2.04 kW/TR (book gives 2.04).","explain":"Sum all auxiliary power before dividing by TR."},{"prompt":"Find the EER.","answer":"28.3 kW ÷ 10.69 kW ≈ 2.65 kW/kW.","explain":"EER compares cooling output with electrical input at full load."}],"order":3259},
{"id":"p3-b04-038","paper":3,"topic":"Refrigeration performance","kind":"problem","front":"Water at 20 m³/h is cooled from 17°C to 10°C. What is the refrigeration load in TR?","back":"About 46.3 TR (option a in the book's objective questions).","explain":"Assumes water density of 1000 kg/m³ and specific heat of 1 kcal/kg°C. The book gives 1 TR = 3024 kcal/h of heat removal.","flash":false,"source":"BEE Book 3 Ch 04 p169","steps":[{"prompt":"Find the mass flow of water.","answer":"20 m³/h × 1000 kg/m³ = 20,000 kg/h.","explain":"Mass flow is needed for the heat balance."},{"prompt":"Find the temperature drop.","answer":"17°C − 10°C = 7°C.","explain":"The drop is the heat removed per kg of water."},{"prompt":"Find the heat removed.","answer":"20,000 kg/h × 1 kcal/kg°C × 7°C = 140,000 kcal/h.","explain":"Heat = mass × specific heat × temperature drop."},{"prompt":"Convert to TR.","answer":"140,000 ÷ 3024 ≈ 46.3 TR.","explain":"Matches option a."}],"order":3260},
{"id":"p3-b04-039","paper":3,"topic":"Refrigeration cycles","kind":"problem","front":"A vapour compression system has a COP of 3.0 and a compressor input of 100 kW. What is its refrigeration capacity in TR?","back":"About 85.3 TR (option a in the book's objective questions).","explain":"Cooling output in kW equals COP times power input. Divide by 3.516 kW per TR; the book's option text uses 3.51 kW.","flash":false,"source":"BEE Book 3 Ch 04 p169","steps":[{"prompt":"Find the cooling output.","answer":"COP × power = 3.0 × 100 kW = 300 kW.","explain":"COP is cooling output divided by input."},{"prompt":"Recall the TR conversion.","answer":"1 TR = 3.516 kW (book: 3.51 kW).","explain":"Also 1 TR = 3024 kcal/h."},{"prompt":"Convert to TR.","answer":"300 ÷ 3.516 ≈ 85.3 TR.","explain":"Matches option a."}],"order":3261},
{"id":"p3-b05-001","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"How does ASME use the specific ratio to classify fans, blowers and compressors?","back":"Specific ratio = discharge pressure ÷ suction pressure. Fans: up to 1.11. Blowers: 1.11 to 1.20. Compressors: more than 1.20.","explain":"The specific ratio is the ASME basis for the split, not the pressure alone. Fans move air at low pressure rise, blowers develop more, and compressors go beyond a ratio of 1.20. The book's Table 5.1 also lists pressure rise in mmWg for each class.","flash":true,"source":"BEE Book 3 Ch 05 p173","order":3262},
{"id":"p3-b05-002","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"Why are radial fans called the industrial workhorses of centrifugal fans?","back":"They develop high static pressure (up to about 1400 mm WC) and handle heavily contaminated airstreams. Their simple design suits high temperatures and medium blade tip speeds.","explain":"Simple construction makes radial fans tolerant of dust and heat. They are the default choice for hard duty, but their efficiency is lower than airfoil and backward-curved designs.","flash":false,"source":"BEE Book 3 Ch 05 p174","order":3263},
{"id":"p3-b05-003","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"Why are backward-inclined fans called non-overloading?","back":"Their power reaches a peak and then falls within the usable airflow range, so changes in static pressure do not overload the motor.","explain":"Backward-inclined fans are also more efficient than forward-curved fans. Stable motor loading is the reason the book prefers them where pressure varies.","flash":false,"source":"BEE Book 3 Ch 05 p174","order":3264},
{"id":"p3-b05-004","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"What does a vaneaxial fan add to a tubeaxial fan, and what is its typical pressure limit?","back":"Guide vanes that straighten and direct the flow. Pressure up to about 500 mm WC. It is typically the most energy-efficient fan and should be used whenever possible.","explain":"Straightening the flow makes static pressure less dependent on duct pressure. Vaneaxial fans are the book's first choice where the application allows.","flash":true,"source":"BEE Book 3 Ch 05 p175","order":3265},
{"id":"p3-b05-005","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"What defines a positive-displacement blower, and where is it preferred?","back":"Rotors trap air and push it through the housing, giving a near-constant volume whatever the system pressure. Up to about 1.25 kg/cm². Preferred where material may clog, since it can blow clogged material free.","explain":"Centrifugal blowers lose flow as pressure rises, which suits steady-volume conveying poorly. Positive-displacement units turn slowly (about 3,600 rpm) and are often belt driven so speed can be changed.","flash":false,"source":"BEE Book 3 Ch 05 p176","order":3266},
{"id":"p3-b05-006","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"What are the peak efficiency ranges for airfoil/backward-curved, vaneaxial, tubeaxial and propeller fans?","back":"Airfoil / backward-curved: 79-83%. Vaneaxial: 78-85%. Tubeaxial: 67-72%. Propeller: 45-50%.","explain":"Axial-flow designs with guide vanes and aerofoil-type centrifugal blades sit at the top of the book's table. Use these ranges as a first check against manufacturer data, not as a substitute for it.","flash":false,"source":"BEE Book 3 Ch 05 p173","order":3267},
{"id":"p3-b05-007","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"How much more efficient can aerofoil centrifugal blades be than backward-curved blades, and what limits their use?","back":"Up to about 10% higher efficiency than backward-curved blades. Their use is limited to clean, dust-free air.","explain":"Aerofoil blades are the most efficient centrifugal design, but dust erodes and disturbs them. That is why they suit clean-air duty only.","flash":false,"source":"BEE Book 3 Ch 05 p181","order":3268},
{"id":"p3-b05-008","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"What is the operating point of a fan in a system?","back":"The intersection of the system curve with the fan's static pressure curve. A vertical line from it to the power curve gives the power required.","explain":"The actual flow and pressure are set by system resistance, not by the fan's nameplate alone. Changing the system resistance moves the operating point along the fan curve.","flash":false,"source":"BEE Book 3 Ch 05 p177","order":3269},
{"id":"p3-b05-009","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"By how much do pressure and power rise if fan speed is increased by 10%?","back":"Pressure rises by 21%. Power requirement rises by 33%.","explain":"Pressure scales with speed squared and power with speed cubed: 1.1² = 1.21 and 1.1³ = 1.33. Flow rises by 10% with speed.","flash":true,"source":"BEE Book 3 Ch 05 p179","order":3270},
{"id":"p3-b05-010","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"What safety margin on flow is generally allowed over the maximum process requirement?","back":"About 5% over the maximum flow requirement, agreed with the process equipment supplier.","explain":"Safety margins should be set with the process supplier, not as a default. The book warns that large margins produce oversized fans that run far below design flow at poor efficiency.","flash":true,"source":"BEE Book 3 Ch 05 p182","order":3271},
{"id":"p3-b05-011","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"What safety margins does the book give for boiler induced-draft (ID) fans?","back":"20% on volume and 30% on head (pressure).","explain":"ID fans are sized with larger margins than forced-draft and primary-air fans. The book's margins for FD and PA fans are smaller.","flash":false,"source":"BEE Book 3 Ch 05 p182","order":3272},
{"id":"p3-b05-012","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"What are the consequences of oversizing a fan and letting it run far below its design flow?","back":"It operates at very poor efficiency. Conservative safety margins are the usual cause.","explain":"A fan's efficiency is best near its design flow. Oversizing pushes it to the low-flow end of its curve, wasting energy and capital.","flash":false,"source":"BEE Book 3 Ch 05 p180","order":3273},
{"id":"p3-b05-013","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"Name five items the user should specify to a fan manufacturer for correct selection.","back":"Any five of: design operating point (volume and pressure); normal operating point; maximum continuous rating; low-load operation; minimum and maximum ambient temperature. Others: gas temperature and density, gas composition, dust concentration and nature, control method, supply frequency, altitude.","explain":"Low-load needs are specified separately when the plant will grow later. Ambient temperature and gas composition set the impeller's material of construction.","flash":false,"source":"BEE Book 3 Ch 05 p182","order":3274},
{"id":"p3-b05-014","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"Why must system resistance be checked periodically?","back":"Changes such as duct coatings, lining erosion, or equipment swaps (for example, multi-cyclones replaced by an ESP) can shift the operating point and cut fan efficiency.","explain":"Coatings and erosion change resistance only marginally. A major equipment change can drastically move the operating point, so the fan may need replacing to keep its earlier efficiency.","flash":false,"source":"BEE Book 3 Ch 05 p183","order":3275},
{"id":"p3-b05-015","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"What are the limits of damper control for fan flow?","back":"Dampers add system resistance to change airflow, but they give limited adjustment and are not energy efficient.","explain":"Damper control moves the operating point along the fan curve without changing speed. The book notes dampers are often left at an intermediate position because they are inconvenient to adjust.","flash":false,"source":"BEE Book 3 Ch 05 p185","order":3276},
{"id":"p3-b05-016","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"How far can inlet guide vanes reduce flow while staying energy efficient?","back":"From 100% flow down to about 80%. Below 80% flow, energy efficiency drops sharply.","explain":"Guide vanes pre-swirl the air entering the fan, changing its fan curve. They suit modest flow reductions only.","flash":true,"source":"BEE Book 3 Ch 05 p185","order":3277},
{"id":"p3-b05-017","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"How do variable-pitch axial fan blades save energy?","back":"Blade pitch is changed hydraulically or pneumatically while the fan is running, which substantially modifies the fan characteristic. The book says this gives dramatically higher energy efficiency than the other options it discusses.","explain":"Variable-pitch blades apply to axial-flow fans only. They are ranked above damper and guide-vane options in the book.","flash":false,"source":"BEE Book 3 Ch 05 p185","order":3278},
{"id":"p3-b05-018","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"What is the turn-down ratio of a flow control method, and what limits it?","back":"Turn-down ratio = maximum flow ÷ minimum flow. It is limited by leakage (slip) through dampers or vanes, by the control system for variable-speed drives, or by the fan's own characteristics.","explain":"Even with dampers fully closed, leakage keeps the flow above zero. Stable fan operation needs the system curve to have a positive slope and the fan curve a negative slope.","flash":false,"source":"BEE Book 3 Ch 05 p186","order":3279},
{"id":"p3-b05-019","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"What is the relationship between total, static and velocity pressure?","back":"Total pressure (TP) = static pressure (SP) + velocity pressure (VP), so VP = TP − SP.","explain":"Static pressure is the potential energy the fan puts into the system; it is given up to friction and converted to velocity pressure at the duct inlet. Velocity pressure is what you use to calculate air velocity.","flash":true,"source":"BEE Book 3 Ch 05 p187","order":3280},
{"id":"p3-b05-020","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"Where and how should air velocity be measured in a duct?","back":"In a straight duct at least 3-5 diameters downstream of elbows, branch entries or size changes. Take several traverse readings across the section, preferably on both suction and discharge sides.","explain":"Bends and size changes distort the velocity profile, so readings taken close to them are unreliable. Traverse points on a circular duct are set at fixed concentric areas.","flash":false,"source":"BEE Book 3 Ch 05 p188","order":3281},
{"id":"p3-b05-021","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"Why average the velocities, not the velocity pressures, across a duct?","back":"Velocity varies across the duct. Calculate velocity at each traverse point, then average the velocities. Do not average the velocity pressures.","explain":"Velocity depends on the square root of velocity pressure, so averaging pressures gives a wrong mean. If a full traverse is impossible, the book's approximation is to measure at the centre and multiply the velocity by 0.9.","flash":false,"source":"BEE Book 3 Ch 05 p189","order":3282},
{"id":"p3-b05-022","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"How does excess air in combustion affect fan power, and what should be done?","back":"Excess air increases the FD and ID fan load. Minimising excess air reduces fan power.","explain":"Every extra unit of air the boiler or furnace takes in is air the fans must move. This is a demand-side measure that cuts fan power at the source.","flash":false,"source":"BEE Book 3 Ch 05 p190","order":3283},
{"id":"p3-b05-023","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"Why are cold air in-leaks into a hot flue gas path so damaging to the ID fan?","back":"Cold air increases the density of the flue gases and so the ID fan load. It can choke the fan's capacity and become a bottleneck for the boiler or furnace.","explain":"The density increase raises the fan's power demand for the same gas handling. The book stresses that in-leaks must be minimised in kilns, boilers and furnaces.","flash":false,"source":"BEE Book 3 Ch 05 p191","order":3284},
{"id":"p3-b05-024","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"Name five fan retrofit options for energy saving.","back":"Any five of: high-efficiency impeller with cone; higher-efficiency fan assembly; impeller derating (smaller diameter); hollow FRP aerofoil impeller for axial fans; fan speed reduction by pulley change; two-speed motor or VSD for variable duty; energy-efficient flat or cogged belts; inlet guide vanes in place of discharge damper; duct system improvements.","explain":"Several options cut the fan's duty, others cut transmission losses. The book lists nine options in total.","flash":false,"source":"BEE Book 3 Ch 05 p191","order":3285}
]$cards$::jsonb);
